<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>NOIACORE // INTERCEPTED</title>
<style>
@import url('https://fonts.cdnfonts.com/css/vt323');
@import url('https://fonts.cdnfonts.com/css/share-tech-mono');

*{margin:0;padding:0;box-sizing:border-box}

body{
  background:#000;
  display:flex;
  justify-content:center;
  align-items:center;
  min-height:100vh;
  overflow:hidden;
  font-family:'VT323','Share Tech Mono','Courier New',monospace;
}

.aspect-wrapper{
  width:min(100vw, calc(100vh * 9 / 16));
  height:min(100vh, calc(100vw * 16 / 9));
  position:relative;
  overflow:hidden;
}

.crt-container{
  width:100%;
  height:100%;
  position:relative;
  background:#000;
  overflow:hidden;
  border:2px solid #300;
  box-shadow:0 0 40px rgba(255,0,0,0.15), inset 0 0 80px rgba(0,0,0,0.8);
}

/* CRT Curvature */
.crt-container::before{
  content:'';
  position:absolute;
  inset:0;
  background:radial-gradient(ellipse at center, transparent 60%, rgba(0,0,0,0.7) 100%);
  z-index:100;
  pointer-events:none;
}

/* Scanlines */
.scanlines{
  position:absolute;
  inset:0;
  background:repeating-linear-gradient(
    0deg,
    rgba(0,0,0,0) 0px,
    rgba(0,0,0,0) 1px,
    rgba(0,0,0,0.15) 1px,
    rgba(0,0,0,0.15) 2px
  );
  z-index:90;
  pointer-events:none;
  animation:scanline-move 0.1s linear infinite;
}

@keyframes scanline-move{
  0%{transform:translateY(0)}
  100%{transform:translateY(2px)}
}

/* Moving scan beam */
.scan-beam{
  position:absolute;
  left:0;
  width:100%;
  height:4px;
  background:linear-gradient(180deg, transparent, rgba(0,255,0,0.08), transparent);
  z-index:91;
  pointer-events:none;
  animation:beam 4s linear infinite;
}

@keyframes beam{
  0%{top:-4px}
  100%{top:100%}
}

/* Flicker */
.crt-container::after{
  content:'';
  position:absolute;
  inset:0;
  background:rgba(0,0,0,0);
  z-index:95;
  pointer-events:none;
  animation:flicker 0.15s infinite;
}

@keyframes flicker{
  0%{opacity:0.02}
  5%{opacity:0.04}
  10%{opacity:0}
  15%{opacity:0.03}
  20%{opacity:0}
  50%{opacity:0.02}
  80%{opacity:0.01}
  100%{opacity:0}
}

/* Noise overlay */
.noise{
  position:absolute;
  inset:0;
  z-index:89;
  pointer-events:none;
  opacity:0.04;
  animation:noise-anim 0.2s steps(4) infinite;
}

@keyframes noise-anim{
  0%{background-position:0 0}
  25%{background-position:50% 50%}
  50%{background-position:-50% 25%}
  75%{background-position:25% -50%}
  100%{background-position:0 0}
}

/* Content area */
.content{
  position:relative;
  z-index:10;
  padding:3% 4%;
  height:100%;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  color:#0f0;
  font-size:clamp(10px, 2.2vw, 16px);
}

/* Header */
.header{
  display:flex;
  justify-content:space-between;
  color:#f00;
  font-size:clamp(9px, 1.8vw, 13px);
  border-bottom:1px solid #300;
  padding-bottom:2%;
  text-shadow:0 0 8px #f00;
  line-height:1.6;
}

.header-left, .header-right{
  display:flex;
  flex-direction:column;
}

.header-right{
  text-align:right;
}

.header .classified{
  animation:pulse-red 2s ease-in-out infinite;
}

@keyframes pulse-red{
  0%,100%{opacity:0.7; text-shadow:0 0 5px #f00}
  50%{opacity:1; text-shadow:0 0 15px #f00, 0 0 30px #f00}
}

/* Center content */
.center{
  flex:1;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  text-align:center;
  padding:3% 0;
  gap:1.5vh;
}

.main-name{
  font-size:clamp(28px, 7vw, 52px);
  color:#0f0;
  text-shadow:0 0 10px #0f0, 0 0 20px #0f0, 0 0 40px #0f0;
  letter-spacing:4px;
  animation:glitch-main 3s infinite;
  position:relative;
  margin-bottom:1vh;
}

.main-name::before, .main-name::after{
  content:'belentani';
  position:absolute;
  left:0;
  right:0;
  overflow:hidden;
}

.main-name::before{
  color:#f00;
  animation:glitch-1 2s infinite;
  clip-path:inset(0 0 70% 0);
}

.main-name::after{
  color:#00f;
  animation:glitch-2 2.5s infinite;
  clip-path:inset(70% 0 0 0);
}

@keyframes glitch-main{
  0%,92%,100%{transform:none}
  93%{transform:translate(-3px, 1px) skewX(-2deg)}
  94%{transform:translate(3px, -1px) skewX(2deg)}
  95%{transform:translate(-1px, 2px)}
  96%{transform:none}
}

@keyframes glitch-1{
  0%,90%,100%{transform:none; opacity:0}
  91%{transform:translate(-4px, 0); opacity:0.7}
  92%{transform:translate(4px, 0); opacity:0.7}
  93%{transform:none; opacity:0}
}

@keyframes glitch-2{
  0%,88%,100%{transform:none; opacity:0}
  89%{transform:translate(3px, 0); opacity:0.5}
  90%{transform:translate(-3px, 0); opacity:0.5}
  91%{transform:none; opacity:0}
}

.line{
  color:#0f0;
  text-shadow:0 0 5px #0f0;
  opacity:0;
  transform:translateY(5px);
  animation:typeline 0.3s forwards;
  position:relative;
  line-height:1.6;
}

.cursor-blink::after{
  content:'▌';
  animation:blink 0.8s step-end infinite;
  color:#0f0;
}

@keyframes blink{
  0%,100%{opacity:1}
  50%{opacity:0}
}

.red-box{
  color:#f00;
  border:1px solid #f00;
  padding:1% 3%;
  margin:1vh 0;
  text-shadow:0 0 8px #f00;
  box-shadow:0 0 10px rgba(255,0,0,0.3), inset 0 0 10px rgba(255,0,0,0.1);
  animation:pulse-box 2s ease-in-out infinite;
  position:relative;
  display:inline-block;
}

.red-box::before{
  content:'[ ';
  color:#f00;
}

.red-box::after{
  content:' ]';
  color:#f00;
}

@keyframes pulse-box{
  0%,100%{box-shadow:0 0 10px rgba(255,0,0,0.3), inset 0 0 10px rgba(255,0,0,0.1)}
  50%{box-shadow:0 0 20px rgba(255,0,0,0.6), inset 0 0 20px rgba(255,0,0,0.2)}
}

.big-red{
  font-size:clamp(14px, 3vw, 22px);
  color:#f00;
  border:2px solid #f00;
  padding:2% 4%;
  text-shadow:0 0 10px #f00, 0 0 20px #f00;
  box-shadow:0 0 15px rgba(255,0,0,0.4), inset 0 0 15px rgba(255,0,0,0.15);
  animation:pulse-box 1.5s ease-in-out infinite, glitch-box 5s infinite;
  display:inline-block;
  position:relative;
}

.big-red::before{content:'[ '; color:#f00}
.big-red::after{content:' ]'; color:#f00}

@keyframes glitch-box{
  0%,95%,100%{transform:none}
  96%{transform:translate(-2px, 1px) skewX(-1deg)}
  97%{transform:translate(2px, -1px) skewX(1deg)}
  98%{transform:translate(-1px, 0)}
}

/* Footer */
.footer{
  display:flex;
  justify-content:space-between;
  color:#f00;
  font-size:clamp(9px, 1.8vw, 13px);
  border-top:1px solid #300;
  padding-top:2%;
  text-shadow:0 0 5px #f00;
  line-height:1.6;
}

.footer-left, .footer-right{
  display:flex;
  flex-direction:column;
}

.footer-right{
  text-align:right;
}

.status-armed{
  animation:armed-flash 1s step-end infinite;
}

@keyframes armed-flash{
  0%,100%{color:#f00; text-shadow:0 0 10px #f00}
  50%{color:#ff0; text-shadow:0 0 10px #ff0, 0 0 20px #ff0}
}

/* Glitch bars */
.glitch-bar{
  position:absolute;
  left:0;
  width:100%;
  height:2px;
  background:#0f0;
  opacity:0;
  z-index:80;
  pointer-events:none;
  animation:glitch-bar-anim 8s infinite;
}

@keyframes glitch-bar-anim{
  0%,94%,100%{opacity:0; transform:scaleX(0)}
  95%{opacity:0.6; transform:scaleX(1); top:30%}
  96%{opacity:0; transform:scaleX(0)}
  97%{opacity:0.4; transform:scaleX(0.8); top:60%}
  98%{opacity:0; transform:scaleX(0)}
}

/* Random glitch artifacts */
.artifact{
  position:absolute;
  background:#0f0;
  opacity:0;
  z-index:85;
  pointer-events:none;
}

/* Sound indicator */
.sound-toggle{
  position:absolute;
  top:2%;
  right:3%;
  z-index:200;
  color:#0f0;
  font-family:'VT323',monospace;
  font-size:clamp(10px, 2vw, 14px);
  cursor:pointer;
  border:1px solid #0f0;
  padding:2px 8px;
  background:rgba(0,0,0,0.8);
  text-shadow:0 0 5px #0f0;
  transition:all 0.3s;
}

.sound-toggle:hover{
  background:rgba(0,255,0,0.1);
  box-shadow:0 0 10px rgba(0,255,0,0.3);
}

.sound-toggle.active{
  color:#0f0;
  border-color:#0f0;
}

.sound-toggle.inactive{
  color:#f00;
  border-color:#f00;
  text-shadow:0 0 5px #f00;
}

/* Chromatic aberration on whole screen */
.chromatic{
  animation:chromatic-shift 10s infinite;
}

@keyframes chromatic-shift{
  0%,90%,100%{filter:none}
  92%{filter:url(#chromatic)}
  94%{filter:none}
  96%{filter:url(#chromatic)}
  97%{filter:none}
}

/* Typing animation */
@keyframes typeline{
  to{opacity:1; transform:translateY(0)}
}

/* VHS tracking */
.vhs-track{
  position:absolute;
  left:0;
  width:100%;
  height:20px;
  background:linear-gradient(transparent, rgba(255,255,255,0.03), transparent);
  z-index:88;
  pointer-events:none;
  animation:vhs-move 6s linear infinite;
}

@keyframes vhs-move{
  0%{top:-20px}
  100%{top:calc(100% + 20px)}
}

/* Power LED */
.power-led{
  position:absolute;
  bottom:1.5%;
  left:50%;
  transform:translateX(-50%);
  width:6px;
  height:6px;
  border-radius:50%;
  background:#0f0;
  box-shadow:0 0 5px #0f0, 0 0 10px #0f0;
  z-index:200;
  animation:led-pulse 3s ease-in-out infinite;
}

@keyframes led-pulse{
  0%,100%{opacity:0.6; box-shadow:0 0 5px #0f0}
  50%{opacity:1; box-shadow:0 0 10px #0f0, 0 0 20px #0f0}
}

/* Responsive adjustments */
@media (max-width:400px){
  .content{font-size:10px; padding:2% 3%}
  .header,.footer{font-size:8px}
}
</style>
</head>
<body>

<!-- SVG Filters -->
<svg style="position:absolute;width:0;height:0">
  <defs>
    <filter id="chromatic">
      <feOffset in="SourceGraphic" dx="2" dy="0" result="red"/>
      <feOffset in="SourceGraphic" dx="-2" dy="0" result="blue"/>
      <feBlend in="red" in2="blue" mode="screen"/>
    </filter>
    <filter id="noise-filter">
      <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="4" stitchTiles="stitch" result="noise"/>
      <feColorMatrix in="noise" type="saturate" values="0" result="gray-noise"/>
      <feBlend in="SourceGraphic" in2="gray-noise" mode="multiply"/>
    </filter>
  </defs>
</svg>

<div class="aspect-wrapper">
  <div class="crt-container chromatic" id="crt">

    <!-- Overlays -->
    <div class="scanlines"></div>
    <div class="scan-beam"></div>
    <div class="vhs-track"></div>
    <div class="glitch-bar"></div>
    <div class="glitch-bar" style="animation-delay:-3s"></div>
    <canvas class="noise" id="noiseCanvas"></canvas>

    <!-- Sound Toggle -->
    <div class="sound-toggle inactive" id="soundToggle" onclick="toggleSound()">
      🔇 SOUND OFF
    </div>

    <!-- Power LED -->
    <div class="power-led"></div>

    <!-- Main Content -->
    <div class="content">

      <!-- Header -->
      <div class="header">
        <div class="header-left">
          <span>NOIACORE</span>
          <span>INTERCEPTED //</span>
          <span>ARCHETYPE PROTOCOL</span>
          <span>v6.4.7</span>
        </div>
        <div class="header-right">
          <span>// INTERNAL</span>
          <span class="classified">// CLASSIFIED</span>
          <span>// LEVEL 0</span>
        </div>
      </div>

      <!-- Center -->
      <div class="center" id="centerContent">
        <div class="main-name" id="mainName">belentani</div>
        <div class="line cursor-blink" style="animation-delay:0.5s">Stay calm</div>
        <div class="line" style="animation-delay:1s">peak of betrayal achieved</div>
        <div class="red-box line" style="animation-delay:1.5s">They failed again</div>
        <div class="line" style="animation-delay:2s">reporting to archetype's</div>
        <div class="line" style="animation-delay:2.3s">architects</div>
        <div class="line cursor-blink" style="animation-delay:2.8s">belentani, you did your job</div>
        <div class="big-red line" style="animation-delay:3.5s">Deploy the kindness<br>revenge now.</div>
      </div>

      <!-- Footer -->
      <div class="footer">
        <div class="footer-left">
          <span>MISSION: KINDNESS REVENGE</span>
          <span>STATUS: <span class="status-armed">ARMED</span></span>
          <span>TARGET: SYSTEMIC HYPOCRISY</span>
          <span>INITIATE: NOW</span>
        </div>
        <div class="footer-right">
          <span>41.3851° N</span>
          <span>2.1734° E</span>
          <span>NOIACORE</span>
        </div>
      </div>

    </div>

    <!-- Random artifacts -->
    <div class="artifact" id="art1"></div>
    <div class="artifact" id="art2"></div>
    <div class="artifact" id="art3"></div>

  </div>
</div>

<script>
// ===== NOISE CANVAS =====
const noiseCanvas = document.getElementById('noiseCanvas');
const nCtx = noiseCanvas.getContext('2d');

function resizeNoise(){
  noiseCanvas.width = noiseCanvas.offsetWidth / 4;
  noiseCanvas.height = noiseCanvas.offsetHeight / 4;
}
resizeNoise();
window.addEventListener('resize', resizeNoise);

function drawNoise(){
  const w = noiseCanvas.width, h = noiseCanvas.height;
  const imgData = nCtx.createImageData(w, h);
  const d = imgData.data;
  for(let i = 0; i < d.length; i += 4){
    const v = Math.random() * 255;
    d[i] = v;
    d[i+1] = v;
    d[i+2] = v;
    d[i+3] = 255;
  }
  nCtx.putImageData(imgData, 0, 0);
  requestAnimationFrame(drawNoise);
}
drawNoise();

// ===== RANDOM GLITCH ARTIFACTS =====
const artifacts = [
  document.getElementById('art1'),
  document.getElementById('art2'),
  document.getElementById('art3')
];

function spawnArtifact(){
  const a = artifacts[Math.floor(Math.random() * artifacts.length)];
  const isGreen = Math.random() > 0.4;
  a.style.background = isGreen ? '#0f0' : '#f00';
  a.style.top = Math.random() * 100 + '%';
  a.style.left = Math.random() * 80 + '%';
  a.style.width = (Math.random() * 30 + 5) + '%';
  a.style.height = (Math.random() * 3 + 1) + 'px';
  a.style.opacity = Math.random() * 0.3 + 0.1;
  a.style.transform = `skewX(${(Math.random()-0.5)*10}deg)`;

  setTimeout(() => {
    a.style.opacity = 0;
  }, 50 + Math.random() * 150);

  setTimeout(spawnArtifact, 200 + Math.random() * 2000);
}
spawnArtifact();

// ===== AUDIO ENGINE =====
let audioCtx = null;
let soundEnabled = false;
let masterGain = null;
let ambientOsc = null;
let ambientGain = null;
let noiseNode = null;
let noiseGain = null;

function initAudio(){
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  masterGain = audioCtx.createGain();
  masterGain.gain.value = 0.3;
  masterGain.connect(audioCtx.destination);

  // Ambient hum
  ambientOsc = audioCtx.createOscillator();
  ambientOsc.type = 'sawtooth';
  ambientOsc.frequency.value = 55;
  ambientGain = audioCtx.createGain();
  ambientGain.gain.value = 0.02;

  const ambientFilter = audioCtx.createBiquadFilter();
  ambientFilter.type = 'lowpass';
  ambientFilter.frequency.value = 200;

  ambientOsc.connect(ambientFilter);
  ambientFilter.connect(ambientGain);
  ambientGain.connect(masterGain);
  ambientOsc.start();

  // Background noise (static)
  const bufferSize = audioCtx.sampleRate * 2;
  const noiseBuffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
  const output = noiseBuffer.getChannelData(0);
  for(let i = 0; i < bufferSize; i++){
    output[i] = Math.random() * 2 - 1;
  }

  noiseNode = audioCtx.createBufferSource();
  noiseNode.buffer = noiseBuffer;
  noiseNode.loop = true;

  noiseGain = audioCtx.createGain();
  noiseGain.gain.value = 0.015;

  const noiseFilter = audioCtx.createBiquadFilter();
  noiseFilter.type = 'bandpass';
  noiseFilter.frequency.value = 3000;
  noiseFilter.Q.value = 0.5;

  noiseNode.connect(noiseFilter);
  noiseFilter.connect(noiseGain);
  noiseGain.connect(masterGain);
  noiseNode.start();

  // Periodic type sounds
  scheduleTypeSounds();
  scheduleBeeps();
  scheduleGlitchSounds();
}

function playTypeSound(){
  if(!audioCtx || !soundEnabled) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();

  osc.type = 'square';
  osc.frequency.value = 800 + Math.random() * 400;

  gain.gain.setValueAtTime(0.06, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.05);

  osc.connect(gain);
  gain.connect(masterGain);

  osc.start(audioCtx.currentTime);
  osc.stop(audioCtx.currentTime + 0.05);
}

function playBeep(freq = 1200, duration = 0.1){
  if(!audioCtx || !soundEnabled) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();

  osc.type = 'sine';
  osc.frequency.value = freq;

  gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);

  osc.connect(gain);
  gain.connect(masterGain);

  osc.start(audioCtx.currentTime);
  osc.stop(audioCtx.currentTime + duration);
}

function playGlitchSound(){
  if(!audioCtx || !soundEnabled) return;
  const bufferSize = audioCtx.sampleRate * 0.1;
  const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
  const data = buffer.getChannelData(0);
  for(let i = 0; i < bufferSize; i++){
    data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.3));
  }

  const source = audioCtx.createBufferSource();
  source.buffer = buffer;

  const gain = audioCtx.createGain();
  gain.gain.value = 0.1;

  const filter = audioCtx.createBiquadFilter();
  filter.type = 'highpass';
  filter.frequency.value = 2000;

  source.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);

  source.start();
}

function scheduleTypeSounds(){
  if(!soundEnabled) return;
  const interval = 100 + Math.random() * 300;
  setTimeout(() => {
    playTypeSound();
    scheduleTypeSounds();
  }, interval);
}

function scheduleBeeps(){
  if(!soundEnabled) return;
  const interval = 2000 + Math.random() * 4000;
  setTimeout(() => {
    playBeep(800 + Math.random() * 800, 0.05 + Math.random() * 0.1);
    scheduleBeeps();
  }, interval);
}

function scheduleGlitchSounds(){
  if(!soundEnabled) return;
  const interval = 3000 + Math.random() * 8000;
  setTimeout(() => {
    playGlitchSound();
    scheduleGlitchSounds();
  }, interval);
}

function toggleSound(){
  const btn = document.getElementById('soundToggle');

  if(!soundEnabled){
    soundEnabled = true;
    if(!audioCtx) initAudio();
    else audioCtx.resume();

    btn.textContent = '🔊 SOUND ON';
    btn.classList.remove('inactive');
    btn.classList.add('active');

    scheduleTypeSounds();
    scheduleBeeps();
    scheduleGlitchSounds();
  } else {
    soundEnabled = false;
    if(audioCtx) audioCtx.suspend();

    btn.textContent = '🔇 SOUND OFF';
    btn.classList.remove('active');
    btn.classList.add('inactive');
  }
}

// ===== PERIODIC SCREEN GLITCH =====
function screenGlitch(){
  const crt = document.getElementById('crt');
  crt.style.transform = `translate(${(Math.random()-0.5)*4}px, ${(Math.random()-0.5)*2}px) skewX(${(Math.random()-0.5)*2}deg)`;

  setTimeout(() => {
    crt.style.transform = 'none';
  }, 50 + Math.random() * 100);

  setTimeout(screenGlitch, 3000 + Math.random() * 10000);
}
setTimeout(screenGlitch, 2000);

// ===== TYPING EFFECT FOR LINES =====
const lines = document.querySelectorAll('.line');
lines.forEach((line, i) => {
  const originalText = line.innerHTML;
  line.style.opacity = '0';

  setTimeout(() => {
    line.style.opacity = '1';
    line.style.transform = 'translateY(0)';
    if(soundEnabled) playTypeSound();
  }, 500 + i * 400);
});

// ===== COORDINATE FLICKER =====
const coordElements = document.querySelectorAll('.footer-right span');
setInterval(() => {
  const el = coordElements[Math.floor(Math.random() * coordElements.length)];
  if(el){
    el.style.opacity = '0.3';
    setTimeout(() => { el.style.opacity = '1'; }, 100);
  }
}, 2000);

// ===== INTERACTIVE: Click anywhere for glitch burst =====
document.addEventListener('click', (e) => {
  if(e.target.id === 'soundToggle') return;

  const crt = document.getElementById('crt');
  crt.style.filter = 'brightness(1.5) contrast(1.3)';

  if(soundEnabled){
    playGlitchSound();
    playBeep(400, 0.15);
  }

